import{_ as e,o as i,c as s,a2 as a}from"./chunks/framework.DaUU7NnF.js";const k=JSON.parse('{"title":"Troubleshooting: Authentication","description":"Diagnose OAuth, token, and credential problems","frontmatter":{"title":"Troubleshooting: Authentication","description":"Diagnose OAuth, token, and credential problems","audience":["operator","user"],"symptoms":["not authorized","token expired","login failed","OAuth error"]},"headers":[],"relativePath":"troubleshooting/authentication.md","filePath":"troubleshooting/authentication.md","lastUpdated":1775243305000}'),n={name:"troubleshooting/authentication.md"};function h(o,t,l,r,d,p){return i(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="authentication-issues" tabindex="-1">Authentication Issues <a class="header-anchor" href="#authentication-issues" aria-label="Permalink to &quot;Authentication Issues&quot;">​</a></h1><p>OAuth flows failing, &quot;not authorized&quot; errors, or token problems. Work through the checks for your service.</p><h2 id="check-1-do-you-have-permission-to-authenticate" tabindex="-1">Check 1: Do you have permission to authenticate? <a class="header-anchor" href="#check-1-do-you-have-permission-to-authenticate" aria-label="Permalink to &quot;Check 1: Do you have permission to authenticate?&quot;">​</a></h2><p>Hookshot&#39;s permission system controls who can log in. The minimum level is <code>login</code>.</p><p>In a DM with the hookshot bot, send:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!hookshot help</span></span></code></pre></div><p>If the bot doesn&#39;t respond or says &quot;no permission&quot;, ask your admin to check the <code>permissions</code> config:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">permissions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">github</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # or &quot;*&quot; for all</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">login</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # minimum for OAuth</span></span></code></pre></div><h2 id="check-2-is-the-service-configured-for-oauth" tabindex="-1">Check 2: Is the service configured for OAuth? <a class="header-anchor" href="#check-2-is-the-service-configured-for-oauth" aria-label="Permalink to &quot;Check 2: Is the service configured for OAuth?&quot;">​</a></h2><h3 id="github" tabindex="-1">GitHub <a class="header-anchor" href="#github" aria-label="Permalink to &quot;GitHub&quot;">​</a></h3><p><code>!github login</code> requires OAuth config:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">github</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  oauth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    client_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Iv1.abc123&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    client_secret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;secret&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    redirect_uri</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://hookshot.example.com/oauth&quot;</span></span></code></pre></div><p>The <code>redirect_uri</code> must match <strong>exactly</strong> what&#39;s configured in the GitHub App settings.</p><p>If missing, <code>!github login</code> will fail silently or return an error.</p><p>Alternative: <code>!github setpersonaltoken &lt;token&gt;</code> doesn&#39;t need OAuth config.</p><h3 id="jira" tabindex="-1">JIRA <a class="header-anchor" href="#jira" aria-label="Permalink to &quot;JIRA&quot;">​</a></h3><p><code>!hookshot jira login</code> requires:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">jira</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  oauth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    client_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-client-id&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    client_secret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-client-secret&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    redirect_uri</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://hookshot.example.com/oauth&quot;</span></span></code></pre></div><h3 id="gitlab" tabindex="-1">GitLab <a class="header-anchor" href="#gitlab" aria-label="Permalink to &quot;GitLab&quot;">​</a></h3><p>GitLab uses personal access tokens, not OAuth:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!hookshot gitlab personaltoken &lt;instance-name&gt; &lt;token&gt;</span></span></code></pre></div><p>The <code>&lt;instance-name&gt;</code> must match an instance defined in config:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">gitlab</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  instances</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    gitlab.com</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://gitlab.com</span></span></code></pre></div><h2 id="check-3-is-the-token-expired" tabindex="-1">Check 3: Is the token expired? <a class="header-anchor" href="#check-3-is-the-token-expired" aria-label="Permalink to &quot;Check 3: Is the token expired?&quot;">​</a></h2><p>Check your auth status:</p><table tabindex="0"><thead><tr><th>Service</th><th>Command</th><th>What it shows</th></tr></thead><tbody><tr><td>GitHub</td><td><code>!github status</code></td><td>Logged-in username or &quot;not authenticated&quot;</td></tr><tr><td>JIRA</td><td><code>!hookshot jira whoami</code></td><td>JIRA identity or error</td></tr><tr><td>GitLab</td><td><code>!hookshot gitlab hastoken &lt;instance&gt;</code></td><td>Whether a token is stored</td></tr></tbody></table><p>If expired:</p><ul><li>GitHub: <code>!github login</code> (re-authenticate) or <code>!github setpersonaltoken &lt;new-token&gt;</code></li><li>JIRA: <code>!hookshot jira login</code> (re-authenticate)</li><li>GitLab: <code>!hookshot gitlab personaltoken &lt;instance&gt; &lt;new-token&gt;</code></li></ul><h2 id="check-4-is-the-redirect-uri-correct" tabindex="-1">Check 4: Is the redirect URI correct? <a class="header-anchor" href="#check-4-is-the-redirect-uri-correct" aria-label="Permalink to &quot;Check 4: Is the redirect URI correct?&quot;">​</a></h2><p>OAuth flows redirect the user to an external service, then back to hookshot. The redirect URI must:</p><ol><li>Match <strong>exactly</strong> between hookshot config and the external service settings</li><li>Be reachable from the user&#39;s browser (not just from hookshot&#39;s server)</li><li>Use HTTPS in production</li></ol><p>Common mistakes:</p><ul><li>Trailing slash mismatch: <code>https://example.com/oauth</code> vs <code>https://example.com/oauth/</code></li><li>HTTP vs HTTPS</li><li>Wrong port or path</li></ul><h2 id="check-5-is-the-token-store-working" tabindex="-1">Check 5: Is the token store working? <a class="header-anchor" href="#check-5-is-the-token-store-working" aria-label="Permalink to &quot;Check 5: Is the token store working?&quot;">​</a></h2><p>Tokens are encrypted with the <code>passFile</code> RSA key. If the passkey changes, all stored tokens become unreadable.</p><p>Symptoms:</p><ul><li>Users were authenticated, then suddenly aren&#39;t after a restart</li><li>Encryption errors in logs</li></ul><p>Fix: Users must re-authenticate (<code>!github login</code>, etc.). There is no way to recover tokens encrypted with a lost passkey.</p><h2 id="check-6-github-app-authentication-instance-level" tabindex="-1">Check 6: GitHub App authentication (instance-level) <a class="header-anchor" href="#check-6-github-app-authentication-instance-level" aria-label="Permalink to &quot;Check 6: GitHub App authentication (instance-level)&quot;">​</a></h2><p>If no webhooks are arriving (separate from user auth), the GitHub App itself may not be authenticating:</p><ol><li>Check the App ID matches <code>github.auth.id</code> in config</li><li>Check the private key file exists and is readable at the path in <code>github.auth.privateKeyFile</code></li><li>Check logs for <code>Failed to authenticate as GitHub App</code> or similar</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Verify the key file is valid</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rsa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github-key.pem</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -noout</span></span></code></pre></div><h2 id="error-messages" tabindex="-1">Error messages <a class="header-anchor" href="#error-messages" aria-label="Permalink to &quot;Error messages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>&quot;You do not have permission&quot;</td><td>Permission level too low</td><td>Admin: set <code>level: login</code> or higher</td></tr><tr><td>&quot;Not authenticated&quot;</td><td>No token stored for this user</td><td>Run the login command for the service</td></tr><tr><td>&quot;Token expired&quot;</td><td>OAuth token expired and refresh failed</td><td>Re-authenticate</td></tr><tr><td>&quot;Invalid redirect_uri&quot;</td><td>Mismatch between config and service settings</td><td>Ensure exact match</td></tr><tr><td>&quot;OAuth state mismatch&quot;</td><td>Stale or replayed OAuth callback</td><td>Retry the login flow</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../understand/trust-and-boundaries">Trust and Boundaries</a> — Auth model overview</li><li><a href="./../integrations/github#authentication">GitHub Integration</a> — GitHub auth details</li><li><a href="./../guides/operator/configuration#permissions">Configuration: Permissions</a></li><li><a href="./">Troubleshooting Index</a></li></ul>`,46)])])}const u=e(n,[["render",h]]);export{k as __pageData,u as default};
